<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Teknisi dan pelimpahan</h1><p>Periksa rekomendasi teknisi dan hubungan dengan perusahaan sebelum akses data diberikan.</p></div></div>
<div data-tabs><div class="admin-tabs" role="tablist"><button class="admin-tab" type="button" role="tab" data-tab="tech" aria-controls="tech-tab" aria-selected="true">Verifikasi teknisi</button><button class="admin-tab" type="button" role="tab" data-tab="link" aria-controls="link-tab" aria-selected="false">Pelimpahan perusahaan</button></div>
<section id="tech-tab" class="card table-card admin-tab-panel" data-tab-panel="tech" role="tabpanel"><div class="filter-results"><strong><?= (int)$tech_pagination['total'] ?> teknisi</strong></div><?php if ($technicians): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Teknisi</th><th>Kontak</th><th>Rekomendasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($technicians as $tech): ?><tr><td data-label="Teknisi"><strong><?= e($tech->full_name) ?></strong><small><?= e($tech->created_at) ?></small></td><td data-label="Kontak"><?= email_html($tech->email) ?><small><?= e($tech->phone) ?> · <?= $tech->phone_verified_at?'WA terverifikasi':'WA belum diverifikasi' ?></small></td><td data-label="Rekomendasi"><?= e($tech->recommendation_number ?: '—') ?><small><?= e($tech->recommendation_note ?: '') ?></small></td><td data-label="Status"><span class="badge <?= $tech->verification_status==='approved'?'success':($tech->verification_status==='pending'?'info':'danger') ?>"><?= e($tech->verification_status) ?></span></td><td data-label="Aksi"><div class="row-actions"><button type="button" class="action-link" data-modal-open="tech-<?= (int)$tech->user_id ?>">Periksa</button><?php if (!$tech->phone_verified_at): ?><form method="post" action="<?= site_url('petugas/teknisi/'.$tech->user_id.'/kode-telepon') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit">Kode manual</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty">Belum ada teknisi.</div><?php endif; ?><?= metro_pager($tech_pagination,'petugas/teknisi',array_filter(array('link_page'=>$link_pagination['page'],'tab'=>'tech'),'strlen'),'tech_page') ?></section>
<section id="link-tab" class="card table-card admin-tab-panel" data-tab-panel="link" role="tabpanel"><div class="filter-results"><strong><?= (int)$link_pagination['total'] ?> hubungan</strong></div><?php if ($links): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Perusahaan</th><th>Teknisi</th><th>Status</th><th>Diajukan</th><th>Aksi</th></tr></thead><tbody><?php foreach ($links as $link): ?><tr><td data-label="Perusahaan"><strong><?= e($link->organization_name ?: $link->company_name) ?></strong></td><td data-label="Teknisi"><?= e($link->technician_name) ?><small><?= e($link->verification_status) ?></small></td><td data-label="Status"><span class="badge <?= $link->status==='active'?'success':($link->status==='pending_office'?'info':'danger') ?>"><?= e($link->status) ?></span></td><td data-label="Diajukan"><?= e(tanggal_id($link->created_at,TRUE)) ?></td><td data-label="Aksi"><button type="button" class="action-link" data-modal-open="link-<?= (int)$link->id ?>">Periksa</button></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty">Belum ada pelimpahan.</div><?php endif; ?><?= metro_pager($link_pagination,'petugas/teknisi',array_filter(array('tech_page'=>$tech_pagination['page'],'tab'=>'link'),'strlen'),'link_page') ?></section></div>
<?php foreach ($technicians as $tech): ?><dialog id="tech-<?= (int)$tech->user_id ?>" class="admin-modal"><div class="modal-head"><div><small>Verifikasi teknisi</small><h2><?= e($tech->full_name) ?></h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/teknisi/nilai/'.$tech->user_id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><label>Nomor rekomendasi dinas<input name="recommendation_number" maxlength="120" value="<?= e($tech->recommendation_number) ?>"></label><label>Catatan penilaian<textarea name="review_note" rows="3" maxlength="1000"><?= e($tech->review_note) ?></textarea></label><p class="muted small">Persetujuan memerlukan nomor telepon terverifikasi dan nomor rekomendasi yang diperiksa dinas.</p></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button outline" name="action" value="reject" type="submit">Tolak</button><button class="button primary" name="action" value="approve" type="submit">Setujui teknisi</button></div></form></dialog><?php endforeach; ?>
<?php foreach ($links as $link): ?><dialog id="link-<?= (int)$link->id ?>" class="admin-modal"><div class="modal-head"><div><small>Pelimpahan perusahaan</small><h2><?= e($link->organization_name ?: $link->company_name) ?></h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/teknisi/pelimpahan/'.$link->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><p>Teknisi: <strong><?= e($link->technician_name) ?></strong></p><p>Status: <?= e($link->status) ?> · Persetujuan pihak kedua: <?= $link->counterpart_accepted_at?'ada':'belum' ?></p><label>Catatan dinas<textarea name="review_note" rows="3" maxlength="1000"><?= e($link->review_note) ?></textarea></label></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><?php if ($link->status==='pending_office'): ?><button class="button outline" name="action" value="reject" type="submit">Tolak</button><button class="button primary" name="action" value="approve" type="submit">Setujui pelimpahan</button><?php elseif ($link->status==='active'): ?><button class="button outline" name="action" value="revoke" type="submit">Cabut akses</button><?php endif; ?></div></form></dialog><?php endforeach; ?>
